```json
{
  "stops": [
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": "m1",
      "note": "Marble Mountains at sunrise? More like first light for the crew. Caves, carvings, and a view that earns its keep."
    },
    {
      "poi_id": "p8",
      "kind": "activity",
      "must_do_id": null,
      "note": "My Khe Beach after the climb. Sand between toes, salt in the air, and not a single stolen snack in sight."
    },
    {
      "poi_id": "p21",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at Mì Quảng Bà Mua. Turmeric noodles, shrimp, pork, and that sesame cracker. Ngon quá."
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "Linh Ứng Pagoda on the way up the peninsula. The Lady Buddha keeps an eye on the sea, and now on you two."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "Sơn Trà afternoon. Green canopy, sea breeze, and maybe a cousin or two watching from the branches."
    },
    {
      "poi_id": "p24",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Hải sản Bé Mặn. Seafood by the water, shells piling up, and the crew finally sitting still."
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": "m3",
      "note": "Bridges at night. Dragon, love locks, and the river doing its best mirror trick. A proper goodnight to the city."
    }
  ]
}
```

